import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>

__global__ void swiglu_half2_kernel(const half* __restrict__ x, half* __restrict__ y, int N, int D){
    int row = blockIdx.x;
    int pair = blockIdx.y * blockDim.x + threadIdx.x;
    int D2 = D >> 1;
    if(row >= N || pair >= D2) return;
    const half* xr = x + ((long long)row) * 2 * D;
    half* yr = y + ((long long)row) * D;
    half2 g2 = reinterpret_cast<const half2*>(xr)[pair];
    half2 u2 = reinterpret_cast<const half2*>(xr + D)[pair];
    float2 g = __half22float2(g2);
    float2 u = __half22float2(u2);
    float r0 = (g.x / (1.0f + __expf(-g.x))) * u.x;
    float r1 = (g.y / (1.0f + __expf(-g.y))) * u.y;
    reinterpret_cast<half2*>(yr)[pair] = __halves2half2(__float2half_rn(r0), __float2half_rn(r1));
}

__global__ void swiglu_half_tail_kernel(const half* __restrict__ x, half* __restrict__ y, int N, int D){
    int row = blockIdx.x;
    if(row < N && (D & 1) && threadIdx.x == 0){
        int col = D - 1;
        const half* xr = x + ((long long)row) * 2 * D;
        float g = __half2float(xr[col]);
        float u = __half2float(xr[col + D]);
        y[((long long)row)*D + col] = __float2half_rn((g / (1.0f + __expf(-g))) * u);
    }
}

template <typename scalar_t>
__global__ void swiglu_kernel(const scalar_t* __restrict__ x, scalar_t* __restrict__ y, int N, int D){
    int row = blockIdx.x;
    int col = blockIdx.y * blockDim.x + threadIdx.x;
    if(row >= N || col >= D) return;
    const scalar_t* xr = x + ((long long)row) * 2 * D;
    float g = (float)xr[col];
    float u = (float)xr[col + D];
    y[((long long)row)*D + col] = (scalar_t)((g / (1.0f + __expf(-g))) * u);
}

void swiglu_forward(torch::Tensor x, torch::Tensor y){
    int N = x.size(0);
    int D = y.size(1);
    if(N==0 || D==0) return;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int threads = 256;
    if(x.scalar_type() == at::kHalf){
        int D2 = D >> 1;
        if(D2 > 0){
